import { readFile } from 'node:fs/promises';
import { join } from 'node:path';

let renderableRoutes: Promise<Array<string>>;

/**
 * Reads the list of renderable doc routes generated by dgeni.
 *
 * @param docsPath The path to the generated docs assets.
 */
export const daffioReadRenderableDocsRoutes = (docsPath: string): Promise<Array<string>> => {
  renderableRoutes ||= readFile(join(docsPath, 'docs', 'renderableRoutes.txt'), 'utf-8').then((content) =>
    content.split('\n').map((route) => route.trim()).filter(Boolean),
  );
  return renderableRoutes;
};
